describe('Filter Result Count Display', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should display correct result count for each filter option', () => {
    // Intercept the search API call
    cy.intercept('GET', '/api/search*').as('searchRequest');

    // Perform a search with multiple filters
    cy.get('[data-testid="search-input"]').type('laptop');
    cy.get('[data-testid="filter-category"]').click();
    cy.get('[data-testid="filter-category-option-electronics"]').click();
    cy.get('[data-testid="filter-price-range"]').click();
    cy.get('[data-testid="filter-price-range-option-0-1000"]').click();
    cy.get('[data-testid="filter-brand"]').click();
    cy.get('[data-testid="filter-brand-option-dell"]').click();

    // Wait for the search results to load
    cy.wait('@searchRequest');

    // Verify the result count for each filter option
    cy.get('[data-testid="filter-category-option-electronics"]').should('contain', '(12)');
    cy.get('[data-testid="filter-price-range-option-0-1000"]').should('contain', '(45)');
    cy.get('[data-testid="filter-brand-option-dell"]').should('contain', '(12)');

    // Verify the total results count is displayed
    cy.get('[data-testid="total-results-count"]').should('be.visible').should('contain', '12');

    // Verify the search results are displayed
    cy.get('[data-testid="search-results-list"]').should('be.visible').should('contain', 'Laptop');
  });

  it('should handle no results scenario and display count as 0', () => {
    // Intercept the search API call with no results
    cy.intercept('GET', '/api/search*', {
      statusCode: 200,
      body: {
        results: [],
        totalCount: 0
      }
    }).as('emptySearchRequest');

    // Perform a search with filters that yield no results
    cy.get('[data-testid="search-input"]').type('tablet');
    cy.get('[data-testid="filter-category"]').click();
    cy.get('[data-testid="filter-category-option-electronics"]').click();
    cy.get('[data-testid="filter-price-range"]').click();
    cy.get('[data-testid="filter-price-range-option-5000-10000"]').click();

    // Wait for the empty search results to load
    cy.wait('@emptySearchRequest');

    // Verify the result count for each filter option is 0
    cy.get('[data-testid="filter-category-option-electronics"]').should('contain', '(0)');
    cy.get('[data-testid="filter-price-range-option-5000-10100"]').should('contain', '(0)');

    // Verify the total results count is displayed as 0
    cy.get('[data-testid="total-results-count"]').should('be.visible').should('contain', '0');

    // Verify no search results are displayed
    cy.get('[data-testid="search-results-list"]').should('be.visible').should('contain', 'No results found');
  });
});
